import sys

def solve_one(n: int, s: str) -> str:
    # rightCnt 统计当前位右侧尚未处理的原始字符数量
    right_cnt = [0] * 26
    for ch in s:
        right_cnt[ord(ch) - ord('a')] += 1

    # leftCnt 统计左侧已确定的最终字符数量
    left_cnt = [0] * 26

    ans = []

    for ch in s:
        idx = ord(ch) - ord('a')

        # 当前字符即将被处理，不再属于右侧，先减去
        right_cnt[idx] -= 1

        # 左侧该字符个数 L 和右侧该字符个数 R
        L = left_cnt[idx]
        R = right_cnt[idx]

        if L == R:
            new_idx = (idx + 1) % 26   # 字母表循环
        else:
            new_idx = idx

        ans.append(chr(new_idx + ord('a')))
        # 最终字符计入左侧
        left_cnt[new_idx] += 1

    return ''.join(ans)

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    pos = 1
    out_lines = []
    for _ in range(t):
        n = int(data[pos]); pos += 1
        s = data[pos]; pos += 1
        out_lines.append(solve_one(n, s))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
```

